(* [comment removed for export] *)
Definition ASEGS : list Segment := Asan.M.loaded_segments.

Definition AT_A : atable :=
  {| img_lo := 0x10000; img_hi := 0x65d000; n_res := 4; shadow_off := 0x7fff8000;
     a_entry := 0x4a8e0; rw_lo := 0xfb000; rw_len := 0x562000; ph_addr_z := 0x10040; ph_ent_z := 56; ph_num_z := 11;
     x_imemset := 0x7ff38; x_imemcpy := 0x7febc; x_memset := 0xf56e4; x_memcpy := 0xf52e0; x_memiszero := 0x80468;
     x_istrncpy := 0x80364; x_sealed := 0x11abe; x_popfree := 0x50f90;
     x_sniff := 0; sniff_tab := 0; sniff_cell := 0;
     x_envscan := 0xe6638; x_envscan_k := 0xe6644; x_pnscan := 0xe66fc; x_pnscan_k := 0xe6708;
     stops_more := [0x765fc; 0x76610; 0x76624; 0x7bfb4; 0x8a64c] (* [comment removed for export] *) |}.


(* [comment removed for export] *)
Definition V_HW : nat := 9.
Definition V_T : nat := 10.
Definition V_P : nat := 11.
(* [comment removed for export] *)
Definition V_R8 : nat := 12.
Definition NXS : nat := 13.
Definition e_top : expr := eadd (escale 32768 (EVar V_S1)) (escale 4096 (EVar V_T)).
Definition ISPD : expr := eadd (escale 32768 (EVar V_S1)) (escale 4096 (EVar V_P)).
(* [comment removed for export] *)
Definition e_bend : expr := eaddz (eadd e_str0 (escale 8 (EVar V_W))) 16.
Definition e_bend64 : expr := eadd e_bend (escale 8 (EVar V_R8)).

(* [comment removed for export] *)
Definition LIMIT_S : Z := StoreOk.RunLim.LMIN.
Definition KC_S : nat := 0.
Definition BFUEL_S : nat := 400000.
Definition FUEL_S : nat := 3000.
(* [comment removed for export] *)
Definition ISP_S : expr := e_sp0.

(* [comment removed for export] *)
Definition WBLK2_LEN : Z := 4194304.
Definition init_vis3 (A : atable) : list (expr * expr) :=
  [(ELit (img_lo A), ELit (img_hi A - img_lo A));
   (EAlu Instr.ALU_ADD e_sp0 (ELit (- STACK_MAX)), ELit STACK_MAX);
   (EAlu Instr.ALU_ADD e_top (ELit (- STACK_MAX)), ELit STACK_MAX);
   (eaddz e_bend64 (- WBLK2_LEN), ELit WBLK2_LEN)].

(* [comment removed for export] *)
Definition init_kn3 (A : atable) : list kentry :=
  [KRange (EVar V_S1) 0xFFFF0000 0xFFFFFFFF; KRange (EVar V_S2) 0 2047;
   KRange (eaddz e_atrandom 16) 0x7fff800000d0 0x800000000000; KRange e_atr8 0xFFFF0000001 0xFFFFFFFFFE7;
   KRange e_sp0 0x7fff80000000 0x7fffffffff30;
   KRange (eadd (escale 4096 (EVar V_S1)) (escale 2 (EVar V_S2))) 0xFFFF0000000 0xFFFFFFFFFE6;
   KRange (EVar V_ARGC) 1 1024; KRange (EVar V_ENVC) 0 256; KRange (EVar V_L0) 0 131071; KRange (EVar V_L1) 0 131071;
   KRange (EVar V_UID) 0 0xFFFFFFFE; KRange (EVar V_HW) 0x112D 0x20112D;
   KRange (EVar V_T) 0 8; KRange (eaddz (esub (escale 16 (EVar V_S2)) (escale 4096 (EVar V_T))) 3935) 0 4095;
   KRange (EVar V_P) 0 7; KRange (esub (escale 16 (EVar V_S2)) (escale 4096 (EVar V_P))) 0 4095;
   KRange (esub (EVar V_T) (EVar V_P)) 0 1;
   KRange (EAlu Instr.ALU_SUB e_sp0 ISPD) 0 4095;   (* [comment removed for export] *)
   KRange (EVar V_R8) 0 7; KRange (eadd e_atr8 (EVar V_R8)) 0xFFFF0000001 0xFFFFFFFFFE7; KRange e_bend64 0x7fff800000d0 0x800000000000;
   KRange (eadd (EAlu Instr.ALU_AND (EAlu Instr.ALU_ADD (EVar V_ARGC) (EAlu Instr.ALU_ADD (EVar V_ENVC) (EAlu Instr.ALU_ADD (EVar V_W) (EMd Instr.M_MUL (ELit 2) (EVar V_S2))))) (ELit 7)) (EVar V_R8)) 7 7;   (* [comment removed for export] *)
   KRange (EVar V_W) 0 280000; KRange (EVar V_BRK) (img_hi A / 4096) ((img_hi A + BRK_ASLR) / 4096);
   KWr (SA e_sp0 (-8388608)) (ELit 8388608); KZero (SA e_sp0 (-8388608)) (ELit 8388608);
   KWord (SA e_sp0 0) 8 (EVar V_ARGC); KWord (SA e_sp0 8) 8 e_str0; kw_argv1 e_argv1w]
  ++ auxw 0 3 (ELit (ph_addr_z A)) ++ auxw 1 4 (ELit (ph_ent_z A)) ++ auxw 2 5 (ELit (ph_num_z A)) ++ auxw 3 16 (EVar V_HW)
  ++ auxw 4 6 (ELit 4096) ++ auxw 5 11 (EVar V_UID) ++ auxw 6 12 (EVar V_UID) ++ auxw 7 23 (ELit 0) ++ auxw 8 25 e_atrandom ++ auxw 9 0 (ELit 0)
  ++ [KUnk (SA (fst e_atrb) (snd e_atrb)) (ELit 16); KWr (SA (fst e_atrb) (snd e_atrb)) (ELit 16);
      KImg (img_lo A) (img_hi A); KWr (SA (ELit 0) (rw_lo A)) (ELit (rw_len A))].

Definition init_abytes (A : atable) : Z := vis_cost (img_hi A - img_lo A) + vis_cost STACK_MAX + vis_cost STACK_MAX + vis_cost WBLK2_LEN.

Definition init_acs3 (A : atable) : acs :=
  ACS (mk_ss (a_entry A) init_regs (init_kn3 A) NXS) [] (img_hi A - img_lo A) MBASE_MIN 0 (init_vis3 A) []
      (init_abytes A) (escale 4096 (EVar V_BRK)) FdStd false (ELit 0) [] (ELit 0).

Definition asan_init_S : acs := init_acs3 AT_A.

(* [comment removed for export] *)
Definition XN_S (id : nat) (args : list expr) (cs : acs) : option acs :=
  match id with
  | 210 => node_nameword NXS cs args
  | 200 => summary_fill AT_A NXS cs (x_imemset AT_A) 256
  | 201 => summary_fill AT_A NXS cs (x_memset AT_A) two64
  | 202 => summary_copy ASEGS AT_A NXS cs (x_imemcpy AT_A)
  | 203 => summary_copy ASEGS AT_A NXS cs (x_memcpy AT_A)
  | 204 => summary_miz AT_A NXS cs
  | 205 => summary_istrncpy AT_A NXS cs
  | 206 => node_envscan AT_A cs
  | 207 => node_pnscan AT_A NXS cs
  | 208 => node_layout cs args
  | 27 => Some cs
  | _ => None
  end%nat.
Definition XE_S (id : nat) (args : list expr) (cs : acs) : option (Z * list spiece * acs) := None.
Definition XB_S (id : nat) (args : list expr) (cs : acs) : option (acs * acs) := None.
Definition XA_S (id : nat) (args : list expr) (cs : acs) : option (acs * acs) := None.

(* [comment removed for export] *)
Definition chkS (IT : itab) (HS : nat -> option acs) (cs : acs) (p : plan) : cres :=
  checkA ASEGS IT AT_A NXS LIMIT_S ISP_S XN_S XE_S XB_S XA_S AP.XT0 HS KC_S true BFUEL_S FUEL_S None cs p.

(* [comment removed for export] *)
Fixpoint subT (s : shape) : bool :=
  match s with
  | SHole _ => true | SNil => true
  | SAlt2 a b => subT a && subT b
  | SCase _ _ a b => subT a && subT b
  | _ => false
  end.
Fixpoint fullT (s : shape) : bool :=
  match s with
  | SHole _ => true
  | SAlt2 a b => (fullT a && subT b) || (subT a && fullT b)
  | SCase _ _ a b => fullT a && fullT b
  | _ => false
  end.
Definition cert_okS (IT : itab) (HS : nat -> option acs) (cs : acs) (p : plan) : bool :=
  match chkS IT HS cs p with COk s => fullT s | _ => false end.
End AsSDefs.
